import{_ as t,o,c as a,a2 as s}from"./chunks/framework.BS2VDJqE.js";const u=JSON.parse('{"title":"Word-form lookup (Hunspell)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/word-forms.md","filePath":"guide/word-forms.md","lastUpdated":1795797533000}'),d={name:"guide/word-forms.md"};function i(n,e,l,r,h,c){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="word-form-lookup-hunspell" tabindex="-1">Word-form lookup (Hunspell) <a class="header-anchor" href="#word-form-lookup-hunspell" aria-label="Permalink to &quot;Word-form lookup (Hunspell)&quot;">​</a></h1><p>Word-form lookup traces an inflected form back to its lemma: looking up <code>hoped</code> also finds <code>hope</code>, and <code>reconstructiveness</code> finds <code>reconstruct</code>.</p><p>The feature is <strong>off by default</strong> and needs external Hunspell files. The reason is that the work happens in the <em>engine</em> rather than inside dictionary content: nothing has to be packed into the <code>.mdx</code>, and any language you can find an <code>.aff</code>/<code>.dic</code> pair for can be supported.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Query</th><th>Result</th></tr></thead><tbody><tr><td><code>hoped</code></td><td><code>hoped</code> (exact entry) + <code>hope</code> (lemma)</td></tr><tr><td><code>rims</code></td><td><code>RIMS</code> (exact entry) + <code>rim</code> (lemma)</td></tr><tr><td><code>fällt</code> (de)</td><td><code>fällt</code> + <code>fallen</code> / <code>fällen</code></td></tr><tr><td><code>abgekämpft</code> (de)</td><td><code>abkämpfen</code></td></tr><tr><td><code>かって</code> (ja)</td><td><code>かって</code> (勝手) / <code>かう</code> (買う) / <code>かつ</code> (勝つ) / <code>かる</code> (狩る)</td></tr><tr><td><code>闲适</code> (zh)</td><td><code>闲适</code> (exact entry) + every spelling your table declares, e.g. <code>閒適</code></td></tr></tbody></table><p>How many lemmas come back depends entirely on the Hunspell files you use — when a form really has several stems, all of them are listed. That is partly Ciyue&#39;s own doing: a stock Hunspell would drop some of them, see <a href="./../internals/word-forms.html#ciyues-hunspell-build">Ciyue&#39;s Hunspell build</a>. For Japanese the stems are kana, with the kanji form shown in parentheses.</p><h2 id="how-to-enable-it" tabindex="-1">How to enable it <a class="header-anchor" href="#how-to-enable-it" aria-label="Permalink to &quot;How to enable it&quot;">​</a></h2><ol><li><strong>Settings → Hunspell</strong> — turn on <em>Enable word-form lookup</em>.</li><li>Import <code>.aff</code> + <code>.dic</code>: pick the folder that contains them, one pair per language. Nothing is bundled with the app.</li><li>Choose a lookup mode (below). For most people, <strong>Supplement</strong> is the more useful choice.</li></ol><p>Stem lookups run in the background, so enabling this does not slow the UI down.</p><h2 id="encoding" tabindex="-1">Encoding <a class="header-anchor" href="#encoding" aria-label="Permalink to &quot;Encoding&quot;">​</a></h2><p>Ciyue sends lookup words to Hunspell as UTF-8 and decodes the results as UTF-8; it does not transcode between encodings. The <code>.aff</code> must declare <code>SET UTF-8</code>, and the <code>.dic</code> must actually be stored as UTF-8.</p><p>Legacy dictionaries still import, and ASCII words may work, but accented or Cyrillic words will not resolve. Some old GoldenDict packs have this problem: “better morphologies” 1.0 uses ISO-8859-1 for <code>es_ES</code> and KOI8-R for <code>ru_RU</code>. Convert both files before importing:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ISO-8859-1 example; use the encoding named by the original SET line</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iconv</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ISO-8859-1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> UTF-8</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> es_ES.aff</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> sed</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;s/^SET .*/SET UTF-8/&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> es_ES.aff.utf8</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iconv</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ISO-8859-1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -t</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> UTF-8</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> es_ES.dic</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> es_ES.dic.utf8</span></span></code></pre></div><p>Verify a few non-ASCII words, then replace the originals. Keep <code>SET UTF-8</code> uppercase and do not add a BOM. GitHub serves the exact bytes committed, so store the converted UTF-8 files in the repository.</p><h2 id="fallback-vs-supplement" tabindex="-1">Fallback vs Supplement <a class="header-anchor" href="#fallback-vs-supplement" aria-label="Permalink to &quot;Fallback vs Supplement&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Query</th><th>Fallback (default)</th><th>Supplement</th></tr></thead><tbody><tr><td><code>rims</code></td><td>only the <code>RIMS</code> entry</td><td><code>RIMS</code> + <code>rim</code></td></tr><tr><td><code>hoped</code></td><td>only the <code>hoped</code> entry</td><td><code>hoped</code> + <code>hope</code></td></tr></tbody></table><p><strong>Fallback</strong> means: stems are only tried when no dictionary has an exact entry. So if a dictionary happens to contain <code>RIMS</code> or <code>hoped</code>, the lemma is never looked up. <strong>Supplement</strong> always shows the stems side by side with the exact entry, which is also what GoldenDict does.</p><p>If a word is found in one mode but not the other, check this switch first.</p><h2 id="where-to-get-hunspell-files" tabindex="-1">Where to get Hunspell files <a class="header-anchor" href="#where-to-get-hunspell-files" aria-label="Permalink to &quot;Where to get Hunspell files&quot;">​</a></h2><p>The Hunspell dictionaries shipped by an operating system (Debian, for example) are usually designed for spell checking only and have <strong>no hand-written <code>st:</code> entries</strong>, so irregular forms cannot be resolved at all. Maintained sets:</p><ul><li>English: <a href="https://github.com/yx-wh/hunspell_en_US" target="_blank" rel="noreferrer">https://github.com/yx-wh/hunspell_en_US</a> — fixed suffix flags, missing stem links and derivation labels, plus an extended word list.</li><li>German: <a href="https://github.com/yx-wh/hunspell_de_DE" target="_blank" rel="noreferrer">https://github.com/yx-wh/hunspell_de_DE</a> — over 2,000 added <code>st:</code> lines for the participles and <code>zu</code>-infinitives of separable verbs.</li><li>Japanese: <a href="https://github.com/yx-wh/hunspell_ja_JP" target="_blank" rel="noreferrer">https://github.com/yx-wh/hunspell_ja_JP</a> — Japanese normally needs no spell checking, so it needs a purpose-built Hunspell dictionary. This set builds on Gary&#39;s original version and adds mixed-script (kana + kanji) to kanji resolution (e.g. まん延 → 蔓延), more verb conjugations, and half-width kana.</li><li>Chinese: <a href="https://github.com/yx-wh/hunspell_zh_CN" target="_blank" rel="noreferrer">https://github.com/yx-wh/hunspell_zh_CN</a> — an empty <code>.aff</code> and a <code>st:</code> table generated from several Chinese dictionaries. The published <code>zh_CN.dic</code> is the pruned build, which is all Ciyue and GoldenDict-ng need; a reader that neither composes characters nor runs OpenCC has to build the full table with the scripts in that repository.</li></ul><h2 id="common-problems" tabindex="-1">Common problems <a class="header-anchor" href="#common-problems" aria-label="Permalink to &quot;Common problems&quot;">​</a></h2><p><strong>Nothing changes after enabling it.</strong> Check three things in order: the toggle, whether any <code>.aff</code>/<code>.dic</code> pair was imported, and the current lookup mode. In Fallback mode, words with an exact hit look exactly as if the feature were off.</p><p><strong><code>hoped</code> still returns <code>hop</code>.</strong> The Hunspell files shipped by an operating system (Debian, for example) carry the <code>hop/D</code> flag, and this <code>.aff</code> does not double the final consonant, so <code>hop + ed</code> produces <code>hoped</code> as well (the correct form is <code>hopped</code>). Switch to the corrected English set above, or remove the <code>D</code> flag from <code>hop</code> yourself.</p><p><strong>German <code>fällt</code> only returns one lemma.</strong> Both <code>fallen</code> and <code>fällen</code> have <code>fällt</code> as their third-person singular, but Hunspell can only report what the <code>.dic</code> declares; a set without the matching <code>st:</code> entries will return fewer.</p><p><strong><code>abzukämpfen</code> / <code>abgekämpft</code> do not resolve.</strong> For separable verbs the <code>zu</code> and <code>ge</code> are infixes, which Hunspell cannot strip — they have to be annotated explicitly with <code>st:</code>. See the German set above.</p><p><strong>One spelling, two <code>st:</code> lines, and only one lemma comes back.</strong> If a <code>.dic</code> lists the same word twice with different <code>st:</code> and neither line carries a flag, a stock build returns only the first: its <code>stem()</code> takes the first <code>st:</code> field of an analysis record, while Ciyue&#39;s patched build returns both — see <a href="./../internals/word-forms.html#ciyues-hunspell-build">Ciyue&#39;s Hunspell build</a>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../internals/word-forms.html">How word-form lookup works</a> — the patched Hunspell build, the Chinese variant-character table, NFC normalisation, and testing a dictionary directly.</li><li><a href="./faq.html">FAQ</a> — dictionary and rendering problems.</li><li><a href="./getting-started.html">Getting started</a> — adding dictionaries.</li></ul>`,29)])])}const m=t(d,[["render",i]]);export{u as __pageData,m as default};
